/** The orderflow command line. */

import { describeEffect } from "./effects.ts";
import { formatHistory, summarize } from "./history.ts";
import { loadOrder, saveOrder } from "./store.ts";
import { EVENTS, TransitionError } from "./types.ts";
import type { EventType } from "./types.ts";
import { allowedEvents, applyEvent } from "./workflow.ts";

export interface Io {
  out: (text: string) => void;
  err: (text: string) => void;
}

const USAGE = `usage: orderflow <command> <order.json> [options]

  show      <order.json>                      print a summary of the order
  events    <order.json>                      list the events the order can take
  history   <order.json>                      print the audit trail
  apply     <order.json> <event> [--at TIME] [--note TEXT] [--write]
                                              apply an event and print what it triggers
`;

function option(args: string[], name: string): string | undefined {
  const index = args.indexOf(name);
  if (index === -1) {
    return undefined;
  }
  const value = args[index + 1];
  if (value === undefined) {
    throw new TransitionError(`${name} needs a value`);
  }
  args.splice(index, 2);
  return value;
}

function flag(args: string[], name: string): boolean {
  const index = args.indexOf(name);
  if (index === -1) {
    return false;
  }
  args.splice(index, 1);
  return true;
}

/** Run the command line; returns the exit status (0, or 2 for any problem). */
export function run(argv: readonly string[], io: Io): number {
  const [command, ...rest] = argv;
  try {
    if (command === "show" || command === "events" || command === "history") {
      const [file, ...extra] = rest;
      if (file === undefined || extra.length > 0) {
        throw new TransitionError(`${command} needs one order file`);
      }
      const order = loadOrder(file);
      if (command === "show") {
        io.out(summarize(order));
      } else if (command === "history") {
        io.out(formatHistory(order.history));
      } else {
        const events = allowedEvents(order.state);
        io.out(events.length === 0 ? "none\n" : `${events.join("\n")}\n`);
      }
      return 0;
    }
    if (command === "apply") {
      const args = [...rest];
      const at = option(args, "--at") ?? new Date().toISOString();
      const note = option(args, "--note");
      const write = flag(args, "--write");
      const [file, type, ...extra] = args;
      if (file === undefined || type === undefined || extra.length > 0) {
        throw new TransitionError("apply needs an order file and an event");
      }
      const event = EVENTS.find((candidate): candidate is EventType => candidate === type);
      if (event === undefined) {
        throw new TransitionError(`unknown event ${JSON.stringify(type)}`);
      }
      const order = loadOrder(file);
      const applied = applyEvent(order, note === undefined ? { type: event } : { type: event, note }, at);
      const lines = [`${order.state} -> ${applied.order.state}`];
      for (const effect of applied.effects) {
        lines.push(`  ${effect}: ${describeEffect(effect)}`);
      }
      io.out(`${lines.join("\n")}\n`);
      if (write) {
        saveOrder(file, applied.order);
      }
      return 0;
    }
    io.err(USAGE);
    return 2;
  } catch (error) {
    if (error instanceof TransitionError) {
      io.err(`orderflow: ${error.message}\n`);
      return 2;
    }
    throw error;
  }
}

/** Plain-language descriptions of the side effects an event triggers. */

const DESCRIPTIONS: Readonly<Record<string, string>> = {
  "email:receipt": "send the payment receipt",
  "email:cancelled": "send the cancellation notice",
  "email:shipped": "send the shipping notice with the tracking link",
  "email:delivered": "send the delivery confirmation",
  "email:return-approved": "send the return approval",
  "email:refund": "send the refund confirmation",
  "warehouse:pick": "ask the warehouse to pick the order",
  "warehouse:pack": "ask the warehouse to pack the order",
  "warehouse:release": "release the reserved stock",
  "carrier:book": "book a pickup with the carrier",
  "carrier:return-label": "create a prepaid return label",
  "payments:refund": "refund the customer's payment",
};

/** What an effect does, in words; an unknown effect is described by its name. */
export function describeEffect(name: string): string {
  return DESCRIPTIONS[name] ?? name;
}

/** Reading and writing order files (JSON). */

import { readFileSync, writeFileSync } from "node:fs";
import { EVENTS, STATES, TransitionError } from "./types.ts";
import type { EventType, HistoryEntry, Order, OrderState } from "./types.ts";

function fail(path: string, message: string): never {
  throw new TransitionError(`${path}: ${message}`);
}

function text(value: unknown, path: string, field: string): string {
  if (typeof value !== "string" || value === "") {
    return fail(path, `${field} must be a non-empty string`);
  }
  return value;
}

function cents(value: unknown, path: string, field: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
    return fail(path, `${field} must be a whole number of cents`);
  }
  return value;
}

function state(value: unknown, path: string, field: string): OrderState {
  const found = STATES.find((candidate) => candidate === value);
  if (found === undefined) {
    return fail(path, `${field} must be one of ${STATES.join(", ")}`);
  }
  return found;
}

function eventType(value: unknown, path: string): EventType {
  const found = EVENTS.find((candidate) => candidate === value);
  if (found === undefined) {
    return fail(path, `history event must be one of ${EVENTS.join(", ")}`);
  }
  return found;
}

function readHistory(value: unknown, path: string): HistoryEntry[] {
  if (!Array.isArray(value)) {
    return fail(path, "history must be a list");
  }
  return value.map((raw: Record<string, unknown>) => ({
    at: text(raw.at, path, "history at"),
    from: state(raw.from, path, "history from"),
    event: eventType(raw.event, path),
    to: state(raw.to, path, "history to"),
    ...(typeof raw.note === "string" ? { note: raw.note } : {}),
  }));
}

/** Read and check an order file. Problems are TransitionErrors that name the file. */
export function loadOrder(path: string): Order {
  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(readFileSync(path, "utf8")) as Record<string, unknown>;
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return fail(path, `cannot read the order: ${reason}`);
  }
  const order: Order = {
    id: text(raw.id, path, "id"),
    customer: text(raw.customer, path, "customer"),
    state: state(raw.state, path, "state"),
    totalCents: cents(raw.totalCents, path, "totalCents"),
    paidCents: cents(raw.paidCents, path, "paidCents"),
    history: readHistory(raw.history ?? [], path),
  };
  if (typeof raw.address === "string") {
    order.address = raw.address;
  }
  if (typeof raw.deliveredAt === "string") {
    order.deliveredAt = raw.deliveredAt;
  }
  return order;
}

/** Write an order file, two-space indented, with a final newline. */
export function saveOrder(path: string, order: Order): void {
  writeFileSync(path, `${JSON.stringify(order, null, 2)}\n`);
}

